  // ---- walkable map: 64×64 cells of 16px over the island picture (lawn, sand path, beach to the dock, dock) ----
  const C = 16, G = 96, GB = 200, OFF = 52, MASK = ""; // v137 mask covers the whole 2560 world (island coords -512..2048)
  const BLOCK = new Set(); // v143 tree trunks block walking until chopped
